import{_ as i,c as a,o as r,aj as t}from"./chunks/framework.8bp-HAn5.js";const g=JSON.parse('{"title":"快捷操作","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"node-quickHand.md","filePath":"node-quickHand.md"}'),e={name:"node-quickHand.md"};function n(o,l,s,p,u,h){return r(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="快捷操作" tabindex="-1">快捷操作 <a class="header-anchor" href="#快捷操作" aria-label="Permalink to “快捷操作”">​</a></h1><p>快捷操作不会产生任何节点，主要针对蓝图进行操作</p><h2 id="重置界面中心点" tabindex="-1">重置界面中心点 <a class="header-anchor" href="#重置界面中心点" aria-label="Permalink to “重置界面中心点”">​</a></h2><p>将蓝图编辑视图重置到中心位置，并自动缩放以显示所有节点。</p><p><strong>说明：</strong></p><ul><li>点击后会计算所有节点的边界范围</li><li>自动将视图移动到中心位置</li><li>自动调整缩放比例，使所有节点都可见</li><li>适用于节点较多、视图混乱时快速定位</li></ul><h2 id="自动设置动画" tabindex="-1">自动设置动画 <a class="header-anchor" href="#自动设置动画" aria-label="Permalink to “自动设置动画”">​</a></h2><p>自动优化骨骼动画节点的设置，简化动画配置流程。</p><p><strong>功能：</strong></p><ul><li>自动检测所有骨骼动画节点</li><li>如果物体只有一个动画，自动设置为循环播放和自动播放</li><li>自动修复柔和过渡设置： <ul><li>如果上一个动画节点连接的是同一个物体，自动关闭柔和过渡</li><li>如果没有上一个动画节点，自动关闭柔和过渡</li></ul></li></ul><p><strong>说明：</strong></p><ul><li>适用于导入旧版数据或批量设置动画节点</li><li>可以快速优化动画播放逻辑</li></ul><h2 id="适配导入旧版数据" tabindex="-1">适配导入旧版数据 <a class="header-anchor" href="#适配导入旧版数据" aria-label="Permalink to “适配导入旧版数据”">​</a></h2><p>适配导入的旧版数据，自动修复和优化节点配置。</p><p><strong>功能：</strong></p><ul><li>自动设置所有骨骼动画节点（同&quot;自动设置动画&quot;功能）</li><li>自动修复数值动画节点： <ul><li>如果动画模式为&quot;变化目标值&quot;，自动同步目标物体的当前属性值</li><li>如果动画模式为&quot;变化多少值&quot;，自动将所有变化量重置为0</li></ul></li></ul><p><strong>说明：</strong></p><ul><li>主要用于导入旧版本蓝图数据后的兼容性处理</li><li>确保旧版数据在新版本中正常工作</li></ul><h2 id="扩散节点" tabindex="-1">扩散节点 <a class="header-anchor" href="#扩散节点" aria-label="Permalink to “扩散节点”">​</a></h2><p>自动调整节点位置，避免节点重叠，向四周扩散排列。</p><p><strong>功能：</strong></p><ul><li>检测所有重叠的节点</li><li>自动将重叠的节点向四周扩散</li><li>保持节点之间的最小间距</li></ul><p><strong>说明：</strong></p><ul><li>适用于导入数据后节点位置混乱的情况</li><li>节点会向各个方向扩散，直到不再重叠</li><li>可能需要多次执行才能完全分离所有节点</li></ul><h2 id="向右扩散节点" tabindex="-1">向右扩散节点 <a class="header-anchor" href="#向右扩散节点" aria-label="Permalink to “向右扩散节点”">​</a></h2><p>自动调整节点位置，避免节点重叠，只向右扩散排列。</p><p><strong>功能：</strong></p><ul><li>检测所有重叠的节点</li><li>自动将重叠的节点向右移动</li><li>保持节点之间的最小间距</li></ul><p><strong>说明：</strong></p><ul><li>与&quot;扩散节点&quot;类似，但只向右移动</li><li>适用于希望保持节点大致在同一水平线上的情况</li><li>节点会向右扩散，直到不再重叠</li></ul><h2 id="优化节点排列" tabindex="-1">优化节点排列 <a class="header-anchor" href="#优化节点排列" aria-label="Permalink to “优化节点排列”">​</a></h2><p>智能排列节点，按照逻辑关系组织节点布局。</p><p><strong>功能：</strong></p><ul><li>将物体节点排列在最左侧</li><li>将与物体关联的节点（如动画、数值动画等）排列在物体右侧</li><li>将独立的音频节点排列在最下方</li><li>按照节点的层级和连接关系组织布局</li></ul><p><strong>说明：</strong></p><ul><li>这是最智能的排列方式</li><li>会考虑节点的连接关系，将相关节点放在一起</li><li>适用于需要整体优化蓝图布局的情况</li></ul><h2 id="折叠节点" tabindex="-1">折叠节点 <a class="header-anchor" href="#折叠节点" aria-label="Permalink to “折叠节点”">​</a></h2><p>折叠节点，隐藏节点的详细属性，只显示标题。</p><p><strong>子菜单：</strong></p><ul><li>折叠所有节点：折叠蓝图中的所有节点</li><li>折叠物体节点：只折叠物体类型的节点</li><li>折叠动画节点：只折叠动画类型的节点</li><li>折叠数值动画节点：只折叠数值动画类型的节点</li><li>折叠输出节点：只折叠输出类型的节点</li></ul><p><strong>说明：</strong></p><ul><li>折叠后可以节省编辑空间，方便查看整体结构</li><li>折叠的节点仍然可以正常连接和使用</li></ul><h2 id="展开节点" tabindex="-1">展开节点 <a class="header-anchor" href="#展开节点" aria-label="Permalink to “展开节点”">​</a></h2><p>展开节点，显示节点的详细属性。</p><p><strong>子菜单：</strong></p><ul><li>展开所有节点：展开蓝图中的所有节点</li><li>展开物体节点：只展开物体类型的节点</li><li>展开动画节点：只展开动画类型的节点</li><li>展开数值动画节点：只展开数值动画类型的节点</li><li>展开输出节点：只展开输出类型的节点</li></ul><p><strong>说明：</strong></p><ul><li>展开后可以查看和编辑节点的详细属性</li><li>与&quot;折叠节点&quot;功能相对应</li></ul><h2 id="音频库" tabindex="-1">音频库 <a class="header-anchor" href="#音频库" aria-label="Permalink to “音频库”">​</a></h2><p>打开音频资源库，查看和管理当前绘本中使用的所有音频资源。</p><p><strong>功能：</strong></p><ul><li>显示所有音频资源的列表</li><li>显示每个音频在哪些分镜中被使用</li><li>可以查看音频的详细信息</li><li>支持替换和删除音频资源</li></ul><p><strong>说明：</strong></p><ul><li>音频库会扫描当前绘本的所有分镜</li><li>列出所有&quot;播放音频&quot;节点使用的音频文件</li><li>方便统一管理音频资源</li></ul><h2 id="动画库" tabindex="-1">动画库 <a class="header-anchor" href="#动画库" aria-label="Permalink to “动画库”">​</a></h2><p>打开动画资源库，查看和管理当前绘本中使用的所有Spine动画资源。</p><p><strong>功能：</strong></p><ul><li>显示所有Spine动画资源的列表</li><li>显示每个动画在哪些分镜中被使用</li><li>可以查看动画的详细信息</li><li>支持替换和删除动画资源</li></ul><p><strong>说明：</strong></p><ul><li>动画库会扫描当前绘本的所有分镜</li><li>列出所有&quot;物体&quot;节点使用的Spine动画文件</li><li>方便统一管理动画资源</li></ul><h2 id="图片库" tabindex="-1">图片库 <a class="header-anchor" href="#图片库" aria-label="Permalink to “图片库”">​</a></h2><p>打开图片资源库，查看和管理当前绘本中使用的所有图片资源。</p><p><strong>功能：</strong></p><ul><li>显示所有图片资源的列表</li><li>显示每个图片在哪些分镜中被使用</li><li>可以查看图片的详细信息</li><li>支持替换和删除图片资源</li></ul><p><strong>说明：</strong></p><ul><li>图片库会扫描当前绘本的所有分镜</li><li>列出所有&quot;物体&quot;节点使用的图片文件</li><li>方便统一管理图片资源</li></ul>',66)])])}const c=i(e,[["render",n]]);export{g as __pageData,c as default};
